import { writeFile } from 'node:fs/promises'; import { join } from 'node:path';
const regions = { 'lower-left': { x: 60, y: 441, width: 220, height: 222 } };
export async function calculate({ outputDir, args }) { const region = regions[args.fixtureRegion]; if (!region) throw Error(`Unknown fixture region: ${args.fixtureRegion}`); const crop={schema:'discstudio-nctk-crop@1',sourcePart:'parts/source/discstudio-fixture',sourceClassification:'DERIVED_FIXTURE_NOT_CREATOR_PHOTO',sourceDimensions:[960,730],region,outputDimensions:[512,512],encoding:'image/webp',quality:.86}; const output=join(outputDir,'crop-settings.json'); await writeFile(output,JSON.stringify(crop,null,2)+'\n'); return {files:[output],observation:{cropSettingsRetained:true,sourceClassification:crop.sourceClassification,region}}; }
